import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BTLSZHNB.js";const m=JSON.parse('{"title":"Content-addressed artifact transport (artifacts.takoform.com/v1alpha1)","description":"","frontmatter":{},"headers":[],"relativePath":"spec/artifact-transport/index.md","filePath":"spec/artifact-transport/index.md"}'),o={name:"spec/artifact-transport/index.md"};function n(d,e,l,r,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="content-addressed-artifact-transport-artifacts-takoform-com-v1alpha1" tabindex="-1">Content-addressed artifact transport (artifacts.takoform.com/v1alpha1) <a class="header-anchor" href="#content-addressed-artifact-transport-artifacts-takoform-com-v1alpha1" aria-label="Permalink to &quot;Content-addressed artifact transport (artifacts.takoform.com/v1alpha1)&quot;">​</a></h1><p>The v1alpha3 lane replaces external credential-free artifact URLs with a content-addressed upload API owned by the host (<a href="./../decisions/0012-artifacts-use-content-addressed-upload.html">decision 0012</a>). Desired state references only immutable manifest digests; raw code bytes, upload endpoints, and transport details never enter client state.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><p>Relative to the discovered <code>endpoints.api</code> base (<code>/apis/forms.takoform.com/v1alpha3</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST   {api}/artifacts/uploads                      start an upload; body carries the manifest</span></span>
<span class="line"><span>PUT    {api}/artifacts/uploads/{uploadId}/blobs/{sha256}   upload one missing blob</span></span>
<span class="line"><span>POST   {api}/artifacts/uploads/{uploadId}/commit    verify and commit the manifest</span></span>
<span class="line"><span>GET    {api}/artifacts/{manifestDigest}             read a committed manifest</span></span>
<span class="line"><span>HEAD   {api}/artifacts/blobs/{sha256}               probe blob presence</span></span>
<span class="line"><span>DELETE {api}/artifacts/uploads/{uploadId}           abandon an incomplete upload</span></span></code></pre></div><h2 id="upload-flow" tabindex="-1">Upload flow <a class="header-anchor" href="#upload-flow" aria-label="Permalink to &quot;Upload flow&quot;">​</a></h2><ol><li>The client computes the SHA-256 of every local file and builds a typed manifest (<a href="/schemas/artifacts/v1alpha1/artifact-manifest.schema.json"><code>artifact-manifest-v1alpha1.schema.json</code></a>).</li><li><code>POST /artifacts/uploads</code> submits the manifest. The response is an <code>artifactUploadStatus</code> naming the <code>uploadId</code> and the digests of blobs the host does not already hold.</li><li>The client uploads only the missing blobs. Each <code>PUT</code> body is the exact blob; the host verifies its size and digest on receipt.</li><li><code>POST .../commit</code> re-verifies every blob against the manifest (size, digest, media type, path grammar) and returns the immutable <code>manifestDigest</code>: the RFC 8785 canonical digest of the manifest bytes.</li><li>Desired state (for example a <code>WorkerBundle</code> revision) references the manifest digest only.</li></ol><p>Uploads are resumable: repeating step 2 with the same manifest returns the still-missing blob set, and committing an already-committed manifest is idempotent and returns the same digest. An abandoned <code>uploadId</code> may be garbage-collected by the host; committed manifests and their blobs are retained while any resource references them.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>A host MUST reject, before commit:</p><ul><li>duplicate module or file names;</li><li>absolute paths, <code>..</code> or <code>.</code> segments, backslashes, NUL, invalid UTF-8;</li><li>media types outside the manifest kind&#39;s closed set;</li><li>size or digest mismatches between manifest and received bytes;</li><li>file-count or total-size overruns of the host&#39;s published limits;</li><li>a <code>WorkerBundle</code> whose <code>mainModule</code> is not listed in <code>modules</code>;</li><li>a source map whose target module is absent;</li><li>archive bombs — archives are transport only and never semantic identity.</li></ul><p>Rejections use <code>artifact_invalid</code> (400); a commit referencing a blob that was never uploaded uses <code>artifact_missing</code> (404).</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li>The manifest is data-only: no credentials, endpoints, or host identities.</li><li>A manifest digest is an immutable identity; the same digest MUST resolve to the same canonical manifest bytes on every conforming host that holds it.</li><li>Blob storage, deduplication, and retention policy are host-owned.</li><li>The frozen v1alpha1/v1alpha2 lanes keep their credential-free URL contract (<a href="./../decisions/0002-artifact-urls-are-credential-free-state.html">decision 0002</a>) unchanged.</li></ul>`,14)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
